function today(){return new Intl.DateTimeFormat("sv-SE",{timeZone:"Asia/Seoul",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date())}
function monthRange(){const t=today();const [y,m]=t.split("-").map(Number);return{start:`${y}-${String(m).padStart(2,"0")}-01`,end:`${y}-${String(m).padStart(2,"0")}-${String(new Date(y,m,0).getDate()).padStart(2,"0")}`}}

function customerOutstanding(payments:Payment[],customer:Customer,credit=customerCredit(payments,customer.id,customer.recoveryCredit||0)){return isEformSignedStatus(customer.eformsignStatus)?Math.max(0,customer.contractAmount-customerPaid(payments,customer.id)-credit):0}
function newestFirst<T extends {id:string;createdTime?:string}>(a:T,b:T){return (b.createdTime||"").localeCompare(a.createdTime||"")||b.id.localeCompare(a.id)}
function eformStatus(status?:string){
 const code=(status||"").trim();
 if(!code)return{label:"미발송",tone:"gray" as const};
 const numeric:Record<string,{label:string;tone:"gray"|"blue"|"green"|"amber"|"red"}>={
  "001":{label:"초안",tone:"gray"},
  "002":{label:"문서 작성",tone:"blue"},
  "003":{label:"서명완료",tone:"green"},
  "010":{label:"결재 요청",tone:"amber"},
  "012":{label:"결재 승인",tone:"green"},
  "040":{label:"취소 요청",tone:"amber"},
  "042":{label:"취소",tone:"red"},
  "045":{label:"반려 요청",tone:"red"},
 };
 if(numeric[code])return numeric[code];
 if(code==="doc_complete")return{label:"서명완료",tone:"green" as const};
 if(code.includes("accept_participant")||code.includes("accept_external"))return{label:"서명완료",tone:"green" as const};
 if(code.includes("open"))return{label:"열람",tone:"blue" as const};
 if(code.includes("reject")||code.includes("cancel")||code.includes("revoke")||code.includes("delete"))return{label:"취소/반려",tone:"red" as const};
 if(code.includes("request")||code==="doc_create")return{label:"서명대기",tone:"amber" as const};
 return{label:"상태 확인 필요",tone:"gray" as const};
}
function SearchBox({value,onChange,onReset,placeholder="이름 또는 전화번호 검색"}:{value:string;onChange:(v:string)=>void;onReset?:()=>void;placeholder?:string}){return <div className="flex items-center gap-2"><div className="relative min-w-0 flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><Input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} className="pl-9"/></div>{onReset&&<Button type="button" variant="secondary" onClick={onReset} className="shrink-0">초기화</Button>}</div>}
function StatusTabs<T extends string>({value,onChange,left,right,leftCount,rightCount}:{value:T;onChange:(v:T)=>void;left:{value:T;label:string};right:{value:T;label:string};leftCount?:number;rightCount?:number}){return <div className="grid grid-cols-2 overflow-hidden rounded-lg border border-slate-200 bg-slate-50"><button type="button" onClick={()=>onChange(left.value)} className={`h-10 px-4 text-sm font-bold transition ${value===left.value?"bg-blue-600 text-white shadow-sm":"bg-white text-slate-600 hover:bg-slate-50"}`}>{left.label}{leftCount!==undefined&&<span className={`ml-1.5 text-xs ${value===left.value?"text-blue-100":"text-slate-400"}`}>({leftCount})</span>}</button><button type="button" onClick={()=>onChange(right.value)} className={`h-10 border-l border-slate-200 px-4 text-sm font-bold transition ${value===right.value?"bg-blue-600 text-white shadow-sm":"bg-white text-slate-600 hover:bg-slate-50"}`}>{right.label}{rightCount!==undefined&&<span className={`ml-1.5 text-xs ${value===right.value?"text-blue-100":"text-slate-400"}`}>({rightCount})</span>}</button></div>}
function NumberInput({value,onChange,min=0,className="",disabled=false}:{value:number;onChange:(v:number)=>void;min?:number;className?:string;disabled?:boolean}){const display=value?value.toLocaleString("ko-KR"):"";return <input inputMode="numeric" disabled={disabled} className={`${field} ${className} ${disabled?"bg-slate-100 text-slate-500":""}`} value={display} placeholder="0" onChange={e=>{const raw=e.target.value.replace(/[^0-9-]/g,"");const n=raw===""?0:Number(raw);onChange(Number.isFinite(n)?Math.max(min,n):min)}}/>}
function Label({text,children}:{text:string;children:React.ReactNode}){return <label className="text-sm font-semibold">{text}<div className="mt-1.5">{children}</div></label>}
function DuplicateCustomerBadge({customers,customer}:{customers:Customer[];customer?:Customer}){const tag=duplicateCustomerTag(customers,customer);return tag?<span className="inline-flex shrink-0 rounded-md bg-slate-100 px-1.5 py-0.5 text-[10px] font-bold text-slate-600 ring-1 ring-inset ring-slate-200">{tag}</span>:null}
function CustomerNameCell({customers,customer,fallback="-"}:{customers:Customer[];customer?:Customer;fallback?:string}){return <div className="flex items-center gap-1.5"><span>{customer?.name||fallback}</span><DuplicateCustomerBadge customers={customers} customer={customer}/></div>}
export default function Section(){const {section}=useParams<{section:string}>();if(section==="changes")return <ChangeHistory/>;if(section==="analytics")return <Analytics/>;if(section==="leads")return <DbManagement/>;if(section==="accidents")return <Accidents/>;if(section==="customers"||section==="db")return <Customers/>;if(section==="contracts")return <Contracts/>;if(section==="payments")return <Payments/>;if(section==="repayments")return <Repayments/>;if(section==="settlements")return <Settlements/>;if(section==="lenders")return <Lenders/>;if(section==="board")return <Board/>;return <Customers/>}


