  <Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1280px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["상환일","고객명","연락처","영업 담당자","조율 담당자","업체명","업체 연락수단","업체 연락정보","현재 약속 잔액","계좌/전달정보","상태","연체 횟수","메모",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(r=>{const c=s.customers.find(x=>x.id===r.customerId);return <tr key={r.id} className="border-t border-slate-100"><td className="px-4 py-3">{history(r)&&r.paidDate?r.paidDate:r.dueDate}</td><td className="px-4 py-3 font-semibold"><CustomerNameCell customers={s.customers} customer={c}/></td><td className="px-4 py-3">{c?.phone||"-"}</td><td className="px-4 py-3">{c?.manager||"-"}</td><td className="px-4 py-3">{c?.coordinationManager||"-"}</td><td className="px-4 py-3 font-semibold">{r.lenderName}</td><td className="px-4 py-3">{r.contactType||"-"}</td><td className="px-4 py-3">{r.contactValue||"-"}</td><td className="px-4 py-3"><b>{won(ledgers.get(r.customerId)?.byId.get(r.id)?.remaining||0)}</b><div className="text-[11px] text-slate-500">기록 {won(r.amount)} / 실상환 {won(r.paidAmount||0)}</div></td><td className="max-w-56 truncate px-4 py-3">{r.account||"-"}</td><td className="px-4 py-3"><Badge tone={r.status==="상환완료"||r.status==="종결"?"green":r.status==="연체"||r.status==="추심"?"red":"amber"}>{history(r)?"상환 기록":r.status}</Badge></td><td className="px-4 py-3">{r.dateChangeCount||0}회</td><td className="max-w-44 truncate px-4 py-3">{r.memo||"-"}</td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="secondary" onClick={()=>setEditing(r)}>수정</Button>{statusView==="상환완료"?<Button variant="danger" onClick={()=>setRecordDel(r)}>기록 삭제</Button>:!history(r)&&<Button variant="danger" onClick={()=>setDel(r)}>일정 삭제</Button>}</div></td></tr>})}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card>
  {scheduleCustomer&&<RepaymentScheduleModal open customer={scheduleCustomer} onClose={()=>setScheduleCustomer(null)}/>}
  {editing&&<RepaymentEdit repayment={editing} onClose={()=>setEditing(null)}/>}
