  <ConfirmDelete open={!!recordDel} name={recordDel?`${s.customers.find(c=>c.id===recordDel.customerId)?.name||"고객"}님의 ${recordDel.lenderName} 상환`:"상환"} label="실제 상환 기록" description={recordDel?`실제 상환 ${won(recordDel.paidAmount||0)}을 취소합니다. 실상환 합계와 미상환 잔액이 다시 계산됩니다. 해당 상환 약속도 취소되며 기존 채무 금액은 유지됩니다.`:undefined} onClose={()=>setRecordDel(null)} onConfirm={async()=>{if(recordDel)await s.cancelCompletedRepayment(recordDel.id,recordDel.rowVersion||1)}}/>
