function Settlements(){const s=useAdminStore();const router=useRouter();const def=monthRange();const [start,setStart]=useState(def.start);const [end,setEnd]=useState(def.end);const [appliedStart,setAppliedStart]=useState(def.start);const [appliedEnd,setAppliedEnd]=useState(def.end);const [page,setPage]=useState(1);const [settlePage,setSettlePage]=useState(1);const [open,setOpen]=useState(false);const [editing,setEditing]=useState<Settlement|null>(null);const [form,setForm]=useState<SettlementDraft>(emptySettlement());const [saving,setSaving]=useState(false);const savingRef=useRef(false);const creationId=useRef("");const [saveError,setSaveError]=useState("");const [del,setDel]=useState<SettlementCancellationSnapshot|null>(null);const [deleting,setDeleting]=useState(false);const deletePending=useRef(false);const [deleteError,setDeleteError]=useState("");const [sourceEditing,setSourceEditing]=useState<{customer:Customer;kind:"payment"|"recovery"|"additional"}|null>(null);const baseContractEvents=s.customers.filter(c=>isEformSignedStatus(c.eformsignStatus)&&(c.isAccident?c.contractAmount:(c.baseContractAmount??c.contractAmount))>0).map(c=>({customerId:c.id,date:c.contractDate||c.createdAt,amount:c.isAccident?c.contractAmount:(c.baseContractAmount??c.contractAmount),kind:"최초계약" as const})).filter(x=>inRange(x.date,appliedStart,appliedEnd));const additionalContractEvents=s.additionalContracts.filter(x=>s.customers.some(c=>c.id===x.customerId&&isEformSignedStatus(c.eformsignStatus)&&!c.isAccident)&&x.contractAmount>0).map(x=>({customerId:x.customerId,date:x.contractDate||String(x.createdTime||"").slice(0,10),amount:x.contractAmount,kind:"추가계약" as const})).filter(x=>inRange(x.date,appliedStart,appliedEnd));const contractEvents=[...baseContractEvents,...additionalContractEvents];const revenueEvents=useMemo(()=>buildRevenueEvents(s.payments,s.recoveries,s.recoveryAllocations),[s.payments,s.recoveries,s.recoveryAllocations]);const signedIds=new Set(s.customers.filter(c=>isEformSignedStatus(c.eformsignStatus)).map(c=>c.id));const periodRevenue=revenueEvents.filter(x=>signedIds.has(x.customerId)&&inRange(x.date,appliedStart,appliedEnd));const recoveryRevenueInRange=revenueEvents.filter(x=>x.source==="recovery"&&inRange(x.date,appliedStart,appliedEnd));const revenue=summarizeRevenue(periodRevenue);const contractSales=contractEvents.reduce((sum,x)=>sum+x.amount,0);const contractRealSales=revenue.realSales;const recoverySales=revenue.recoverySuccessFee;const customerIds=new Set([...contractEvents.map(x=>x.customerId),...periodRevenue.map(x=>x.customerId)]);const rows=s.customers.filter(c=>customerIds.has(c.id)).sort(newestFirst);const totalOutstanding=s.customers.filter(c=>isEformSignedStatus(c.eformsignStatus)).reduce((sum,c)=>sum+Math.max(0,c.contractAmount-customerPaid(s.payments,c.id)-customerCredit(s.payments,c.id,c.recoveryCredit||0)),0);const bankRows=useMemo(()=>buildBankCashRows(s.settlements,s.recoveryRefunds,s.customers),[s.settlements,s.recoveryRefunds,s.customers]);const settlementRows=bankCashRowsInRange(bankRows,appliedStart,appliedEnd).sort((a,b)=>(b.paidDate||"").localeCompare(a.paidDate||"")||newestFirst(a,b));const bankTotals=summarizeBankCash(settlementRows);const settlementTotal=bankTotals.net;const settlementInflow=bankTotals.inflow;const settlementOutflow=bankTotals.outflow;const autoSettlementCount=settlementRows.filter(x=>x.entrySource&&x.entrySource!=="manual").length;const manualSettlementCount=settlementRows.length-autoSettlementCount;function resetMonth(){setStart(def.start);setEnd(def.end);setAppliedStart(def.start);setAppliedEnd(def.end);setPage(1);setSettlePage(1)}function beginAdd(){if(savingRef.current||deletePending.current)return;creationId.current=crypto.randomUUID();setSaveError("");setEditing(null);setForm(emptySettlement());setOpen(true)}function beginEdit(x:Settlement){if(savingRef.current||deletePending.current)return;setSaveError("");setEditing(x);setForm({paidDate:x.paidDate,clientName:x.clientName,amount:x.amount,paymentMethod:x.paymentMethod,memo:x.memo});setOpen(true)}async function saveSettlement(){if(savingRef.current)return;savingRef.current=true;setSaving(true);setSaveError("");try{if(editing)await s.updateSettlement(editing.id,form);else{creationId.current ||= crypto.randomUUID();await s.addSettlement(form,creationId.current)}setOpen(false)}catch(error){setSaveError(`정산 저장 실패: ${error instanceof Error?error.message:String(error)}`)}finally{savingRef.current=false;setSaving(false)}}function beginDelete(row:Settlement){if(deletePending.current||savingRef.current)return;setDeleteError("");setDel(createSettlementCancellation(row,s,crypto.randomUUID()))}
 function closeDelete(){if(!deletePending.current){setDel(null);setDeleteError("")}}
 async function cancelSettlement(){if(!del?.expected||deletePending.current)return;const captured=del;deletePending.current=true;setDeleting(true);setDeleteError("");try{await s.deleteSettlement(captured.row.id,captured.expected!,captured.requestKey);setDel(null)}catch(error){setDeleteError(error instanceof Error?error.message:"실제 거래를 취소하지 못했습니다. 다시 시도해주세요.")}finally{deletePending.current=false;setDeleting(false)}}
 function manageSettlementSource(){if(!del||deletePending.current)return;const customer=s.customers.find(item=>item.id===del.customerId);if(customer&&del.manage!=="customers"){setSourceEditing({customer,kind:del.manage});setDel(null);setDeleteError("")}else{router.push("/customers")}}
 function settlementDisplayName(x:Settlement){const customer=x.customerId?s.customers.find(c=>c.id===x.customerId):undefined;const source=x.sourcePaymentScheduleId?s.payments.find(p=>p.id===x.sourcePaymentScheduleId):undefined;const sourceCustomer=source?.customerId?s.customers.find(c=>c.id===source.customerId):undefined;return customer?.name||sourceCustomer?.name||x.clientName}
 function settlementNote(x:Settlement){
 const source=x.sourcePaymentScheduleId?s.payments.find(p=>p.id===x.sourcePaymentScheduleId):undefined;
 if(x.entryType==="환수"||source?.scheduleType==="환수"){
  const recovery=s.recoveries.find(r=>r.id===(x.sourceRecoveryId||source?.sourceRecoveryId));
  return `환수 입금 [${recovery?.lenderName||"업체 미확인"}] [예금주:${recovery?.depositorName?.trim()||"미입력"}]`;
 }
 if(x.entrySource!=="payment")return x.memo;
 if(source?.scheduleType==="추가계약"||/선납/.test(x.memo))return "계약 선납금 입금";
 return "분납금 입금";
 }function settlementPhone(x:Settlement){const direct=x.customerId?s.customers.find(c=>c.id===x.customerId):undefined;if(direct)return direct.phone||"-";const source=x.sourcePaymentScheduleId?s.payments.find(p=>p.id===x.sourcePaymentScheduleId):undefined;const sourceCustomer=source?s.customers.find(c=>c.id===source.customerId):undefined;if(sourceCustomer)return sourceCustomer.phone||"-";const sameName=s.customers.filter(c=>c.name.trim()&&c.name.trim()===x.clientName.trim());return sameName.length===1?(sameName[0].phone||"-"):"-"}function csvCell(v:string|number){return `"${String(v??"").replaceAll('"','""')}"`}function downloadSettlement(){const header=["거래일","의뢰인 성함","연락처","입출금","거래유형","연동","금액","결제 방법","비고"];const body=settlementRows.map(x=>[x.paidDate,settlementDisplayName(x),settlementPhone(x),x.amount<0?"출금":"입금",x.entryType||"계약",(x.entrySource==="payment"||x.entrySource==="recovery")?"자동":x.entrySource==="refund"?"환수 반환":"수기",Math.abs(x.amount),x.paymentMethod,settlementNote(x)]);const csv="\uFEFF"+[header,...body].map(r=>r.map(csvCell).join(",")).join("\r\n");const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`로펌_정산표_${appliedStart}_${appliedEnd}.csv`;a.click();URL.revokeObjectURL(url)}return <div className="dowon-polish dowon-settlements"><PageHeader title="정산" description="기간별 계약·입금·환수 및 입출금 현황"/><Card className="dowon-settlement-filter mb-4 p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><div className="mb-1.5 text-sm font-semibold">조회 기간</div><DateRangePicker start={start} end={end} onChange={(a,b)=>{setStart(a);setEnd(b);setAppliedStart(a);setAppliedEnd(b);setPage(1);setSettlePage(1)}}/></div><div className="flex gap-2"><Button variant="secondary" onClick={resetMonth}>이번달</Button>{([1,2] as const).map(q=><Button key={q} variant="secondary" onClick={()=>{const base=monthRange().start.slice(0,7);const [year,month]=base.split("-").map(Number);const a=`${base}-${q===1?"01":"16"}`;const b=q===1?`${base}-15`:new Date(Date.UTC(year,month,0)).toISOString().slice(0,10);setStart(a);setEnd(b);setAppliedStart(a);setAppliedEnd(b);setPage(1);setSettlePage(1)}}>{q}분기</Button>)}</div></div></Card><div className="dowon-settlement-kpis grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["계약 매출",contractSales],["실매출",contractRealSales],["환수",recoverySales],["현재 미수금",totalOutstanding]].map(([l,v])=><Card key={l as string} className="p-5"><div className="text-sm text-slate-500">{l}</div><div className={`mt-2 text-2xl font-bold ${l==="현재 미수금"?"text-red-600":l==="환수"?"text-emerald-700":""}`}>{won(v as number)}</div></Card>)}</div>
<p className="mt-3 text-xs leading-5 text-slate-500">실매출 = 계약 선납금·분납금 + 환수 분납금 · 환수 = 업체 환수 입금액의 50% 성공보수. 전자서명 완료 고객을 집계합니다.</p>
<Card className="dowon-settlement-ledger mt-4 overflow-hidden"><div className="flex flex-col gap-3 border-b border-slate-100 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="font-bold">로펌 정산표</div><div className="mt-1 text-xs text-slate-500">{appliedStart} ~ {appliedEnd} · 자동연동 {autoSettlementCount}건 · 수기 {manualSettlementCount}건</div><div className="mt-1 text-xs text-slate-500">계좌 대조용 실제 입출금 내역입니다. 업체 환수 입금은 총액 1건으로 표시합니다.</div></div><div className="flex flex-wrap items-center gap-2"><div className="rounded-lg bg-blue-50 px-4 py-2 text-sm font-bold text-blue-700">입금 {won(settlementInflow)} · 출금 {won(settlementOutflow)} · 순입금 {won(settlementTotal)}</div><Button variant="secondary" onClick={downloadSettlement}><Download size={15}/>CSV 다운로드</Button><Button onClick={beginAdd} disabled={deleting}><Plus size={15}/>정산 내역 추가</Button></div></div><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1100px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["거래일","의뢰인 성함","연락처","입출금","구분","연동","금액","결제 방법","비고",""].map(h=><th className="px-4 py-3" key={h}>{h}</th>)}</tr></thead><tbody>{pageRows(settlementRows,settlePage,10).map(x=><tr key={x.id} className="border-t border-slate-100"><td className="px-4 py-3">{x.paidDate}</td><td className="px-4 py-3 font-semibold">{settlementDisplayName(x)}</td><td className="whitespace-nowrap px-4 py-3">{settlementPhone(x)}</td><td className="px-4 py-3">{x.amount<0?<Badge tone="red">출금</Badge>:<Badge tone="green">입금</Badge>}</td><td className="px-4 py-3">{x.amount<0?<Badge tone="amber">{x.entryType||"고객 반환"}</Badge>:x.entryType&&x.entryType!=="계약"?<Badge tone="green">{x.entryType}</Badge>:<Badge tone="blue">계약</Badge>}</td><td className="px-4 py-3">{(x.entrySource==="payment"||x.entrySource==="recovery")?<Badge tone="green">자동연동</Badge>:x.entrySource==="refund"?<Badge tone="amber">환수 반환</Badge>:<Badge tone="gray">수기</Badge>}</td><td className="px-4 py-3 font-semibold text-blue-700">{won(Math.abs(x.amount))}</td><td className="px-4 py-3">{x.paymentMethod}</td><td className="max-w-72 truncate px-4 py-3">{settlementNote(x)||"-"}</td><td className="px-4 py-3"><div className="flex justify-end gap-1">{(!x.entrySource||x.entrySource==="manual")&&<Button variant="secondary" disabled={deleting} onClick={()=>beginEdit(x)}>수정</Button>}<Button variant="danger" disabled={deleting||saving} onClick={()=>beginDelete(x)}>삭제</Button></div></td></tr>)}{settlementRows.length===0&&<tr><td colSpan={10} className="px-4 py-10 text-center text-slate-400">선택한 기간에 로펌 정산 내역이 없습니다.</td></tr>}</tbody></table></div><Pagination page={settlePage} total={settlementRows.length} pageSize={10} onChange={setSettlePage}/></Card>
<Card className="mt-4 p-4"><div className="font-bold">환수 성공보수 배분 내역 (50% · 별도 입금 아님)</div><div className="mt-2 space-y-1 text-sm">{recoveryRevenueInRange.map(event=>{const r=s.recoveries.find(x=>x.id===event.id);const c=s.customers.find(x=>x.id===event.customerId);return <div key={event.id} className="flex flex-wrap justify-between gap-2 border-b py-1"><span>{event.date} · {c?.name||"의뢰인 미확인"} · {r?.lenderName||"업체 미확인"}</span><b>{won(event.recoverySuccessFee)}</b></div>})}{recoveryRevenueInRange.length===0&&<div className="py-2 text-sm text-slate-400">해당 기간에 환수 성공보수 내역이 없습니다.</div>}</div></Card>
<Card className="mt-4 p-4"><div className="font-bold">환수 분납 충당 내역 (내부 배분)</div><p className="mt-1 text-xs text-slate-500">환수금 중 계약 분납채무에 충당된 금액이며 상단 실매출에 포함됩니다. 업체 환수 입금 총액에 포함된 내부 배분이므로 로펌 정산표에 별도 입금을 추가하지 않습니다.</p><div className="mt-3 space-y-2">{recoveryRevenueInRange.filter(event=>event.recoveryInstallment>0).map(event=>{const r=s.recoveries.find(x=>x.id===event.id);const c=s.customers.find(x=>x.id===event.customerId);return <div key={event.id} className="flex flex-wrap justify-between gap-2 rounded-lg border border-slate-100 bg-slate-50 p-3 text-sm"><div><b>{c?.name||"-"}</b> · {event.date}<div className="text-xs text-slate-500">환수 분납 충당 · {r?.lenderName||"-"}</div></div><b className="text-blue-700">{won(event.recoveryInstallment)}</b></div>})}{!recoveryRevenueInRange.some(event=>event.recoveryInstallment>0)&&<div className="py-2 text-sm text-slate-400">해당 기간에 환수 충당 내역이 없습니다.</div>}</div></Card>
<Card className="mt-4 overflow-hidden"><div className="border-b border-slate-100 px-5 py-4"><div className="font-bold">기간별 고객 정산 현황</div><div className="mt-1 text-xs text-slate-500">최초 계약과 추가 계약을 각각의 계약일 기준으로 분리해 해당 기간에 발생한 계약매출만 표시합니다.</div></div><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1080px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["고객명","연락처","영업 담당자","조율 담당자","기간 계약매출","실매출","환수","현재 미수금","상태"].map(h=><th className="px-4 py-3" key={h}>{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(c=>{const baseSales=baseContractEvents.filter(x=>x.customerId===c.id).reduce((sum,x)=>sum+x.amount,0);const additionalSales=additionalContractEvents.filter(x=>x.customerId===c.id).reduce((sum,x)=>sum+x.amount,0);const periodContractSales=baseSales+additionalSales;const customerRevenue=summarizeRevenue(periodRevenue,"","",new Set([c.id]));const periodContractPaid=customerRevenue.realSales;const periodRecovery=customerRevenue.recoverySuccessFee;const due=isEformSignedStatus(c.eformsignStatus)?Math.max(0,c.contractAmount-customerPaid(s.payments,c.id)-customerCredit(s.payments,c.id,c.recoveryCredit||0)):0;return <tr key={c.id} className="border-t border-slate-100"><td className="px-4 py-3 font-semibold">{c.name}</td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3">{c.coordinationManager}</td><td className="px-4 py-3"><div className="font-semibold text-blue-700">{won(periodContractSales)}</div>{periodContractSales>0&&<div className="mt-1 text-[11px] text-slate-400">{baseSales>0?`최초 ${won(baseSales)}`:""}{baseSales>0&&additionalSales>0?" + ":""}{additionalSales>0?`추가 ${won(additionalSales)}`:""}</div>}</td><td className="px-4 py-3 text-blue-700">{won(periodContractPaid)}</td><td className="px-4 py-3 text-emerald-700">{won(periodRecovery)}</td><td className="px-4 py-3 text-red-600">{won(due)}</td><td className="px-4 py-3"><Badge tone={due===0&&c.contractAmount>0?"green":"blue"}>{due===0&&c.contractAmount>0?"종결":"진행"}</Badge></td></tr>})}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card><Modal open={open} title={editing?"정산 내역 수정":"정산 내역 추가"} onClose={()=>setOpen(false)} busy={saving}>{saveError&&<div role="alert" className="mb-4 rounded-xl border border-red-200 bg-red-50 p-3 text-sm font-semibold text-red-700">{saveError}</div>}<div className="grid gap-4 sm:grid-cols-2"><Label text="입금일시"><input type="date" className={field} value={form.paidDate} onChange={e=>setForm({...form,paidDate:e.target.value})}/></Label><Label text="의뢰인 성함"><input className={field} value={form.clientName} onChange={e=>setForm({...form,clientName:e.target.value})} placeholder="예: 홍길동"/></Label><Label text="결제금액"><NumberInput value={form.amount} onChange={v=>setForm({...form,amount:v})}/></Label><Label text="결제 방법"><select className={field} value={form.paymentMethod} onChange={e=>setForm({...form,paymentMethod:e.target.value})}>{paymentMethods.map(x=><option key={x}>{x}</option>)}</select></Label><div className="sm:col-span-2"><Label text="비고"><input className={field} value={form.memo} onChange={e=>setForm({...form,memo:e.target.value})} placeholder="예: 세금계산서 발행"/></Label></div><div className="sm:col-span-2 flex justify-end gap-2"><Button variant="secondary" disabled={saving} onClick={()=>setOpen(false)}>취소</Button><Button onClick={()=>void saveSettlement()} disabled={saving}>{saving?"저장 중...":"저장"}</Button></div></div></Modal><SettlementCancellationDialog snapshot={del} pending={deleting} error={deleteError} onClose={closeDelete} onConfirm={()=>void cancelSettlement()} onManage={manageSettlementSource}/>{sourceEditing?.kind==="recovery"&&<RecoveriesModal open customer={sourceEditing.customer} onClose={()=>setSourceEditing(null)}/>} {sourceEditing?.kind==="additional"&&<AdditionalContractsModal open customer={sourceEditing.customer} onClose={()=>setSourceEditing(null)}/>} {sourceEditing?.kind==="payment"&&<PaymentScheduleModal open customer={sourceEditing.customer} onClose={()=>setSourceEditing(null)}/>}</div>}

const emptyLender=():Omit<Lender,"id">=>({createdAt:today(),name:"",contacts:[{id:`LC-${Date.now()}`,type:"번호",value:""}],account:"",memo:"",customerIds:[]});
function Accidents(){
 const s=useAdminStore();
 const [page,setPage]=useState(1);
 const [q,setQ]=useState("");
 const [view,setView]=useState<"risk"|"accident">("risk");
 const [expandedId,setExpandedId]=useState<string|null>(null);
 const riskRows=useMemo(()=>s.customers.filter(c=>!!c.isAccidentRisk&&!c.isAccident&&`${c.name} ${c.phone} ${c.manager} ${c.coordinationManager} ${c.memo}`.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>(b.accidentRiskMarkedAt||b.createdTime||"").localeCompare(a.accidentRiskMarkedAt||a.createdTime||"")||newestFirst(a,b)),[s.customers,q]);
 const accidentRows=useMemo(()=>s.customers.filter(c=>c.isAccident&&`${c.name} ${c.phone} ${c.manager} ${c.coordinationManager} ${c.memo}`.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>(b.accidentMarkedAt||b.createdTime||"").localeCompare(a.accidentMarkedAt||a.createdTime||"")||newestFirst(a,b)),[s.customers,q]);
 const rows=view==="risk"?riskRows:accidentRows;
 function promote(c:Customer){if(typeof window!=="undefined"&&!window.confirm(`${c.name} 고객을 사고자로 등록하시겠습니까?\n등록 후 사고자 탭으로 이동하며 납부·상환 일정 경고 대상에서 제외됩니다.`))return;s.updateCustomer(c.id,{isAccident:true,isAccidentRisk:false})}
 function release(c:Customer){s.updateCustomer(c.id,{isAccidentRisk:false});if(expandedId===c.id)setExpandedId(null)}
 function releaseAccident(c:Customer){if(typeof window!=="undefined"&&!window.confirm(`${c.name} 고객의 사고자 등록을 해제하시겠습니까?\n\n기존 계약·입금·상환 이력은 삭제되지 않습니다. 사고자 제외 상태가 해제되어 납부·상환 일정 및 알림 대상에 다시 포함될 수 있습니다.`))return;s.updateCustomer(c.id,{isAccident:false,isAccidentRisk:false});if(expandedId===c.id)setExpandedId(null)}
 return <>
  <PageHeader title="사고자 조회" description="사고 가능성이 있는 고객은 먼저 사고 위험자로 관리하고, 실제 사고 발생 시 사고자로 전환합니다." action={<div className="flex gap-2"><Badge tone="amber">사고 위험자 {riskRows.length}명</Badge><Badge tone="red">사고자 {accidentRows.length}명</Badge></div>}/>
  <Card className="mb-4 p-3"><div className="space-y-3"><StatusTabs value={view} onChange={v=>{setView(v);setPage(1);setExpandedId(null)}} left={{value:"risk",label:"사고 위험자"}} right={{value:"accident",label:"사고자"}} leftCount={riskRows.length} rightCount={accidentRows.length}/><SearchBox value={q} onChange={v=>{setQ(v);setPage(1);setExpandedId(null)}} onReset={()=>{setQ("");setPage(1);setExpandedId(null)}} placeholder="고객명, 연락처, 담당자 또는 메모 검색"/></div></Card>
  <Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[1220px] text-sm"><thead className={view==="risk"?"bg-amber-50/70 text-left text-xs text-slate-500":"bg-red-50/60 text-left text-xs text-slate-500"}><tr>{[view==="risk"?"위험자 등록일":"사고자 등록일","고객명","연락처","영업 담당자","조율 담당자","계약금액","실납부액","미수금","업체수","메모","관리"].map((h,i)=><th key={`${h}-${i}`} className="px-4 py-3 font-medium">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page,10).map(c=>{const paid=customerPaid(s.payments,c.id);const originalContractAmount=(c.baseContractAmount??c.contractAmount)+s.additionalContracts.filter(x=>x.customerId===c.id).reduce((sum,x)=>sum+(x.contractAmount||0),0);const outstanding=Math.max(0,originalContractAmount-paid);const expanded=expandedId===c.id;const status=eformStatus(c.eformsignStatus);const rowTone=view==="risk"?`border-amber-100 hover:bg-amber-50 ${expanded?"bg-amber-50":"bg-amber-50/20"}`:`border-red-100 hover:bg-red-50 ${expanded?"bg-red-50":"bg-red-50/25"}`;return <Fragment key={c.id}><tr onClick={()=>setExpandedId(expanded?null:c.id)} className={`cursor-pointer border-t transition ${rowTone}`} title="클릭하면 고객정보를 펼쳐볼 수 있습니다"><td className="whitespace-nowrap px-4 py-3">{view==="risk"?(c.accidentRiskMarkedAt?String(c.accidentRiskMarkedAt).slice(0,10):c.createdAt):(c.accidentMarkedAt?String(c.accidentMarkedAt).slice(0,10):c.createdAt)}</td><td className="px-4 py-3 font-semibold"><div className="flex items-center gap-2"><span>{c.name}</span><Badge tone={view==="risk"?"amber":"red"}>{view==="risk"?"사고 위험자":"사고자"}</Badge></div></td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3">{c.coordinationManager}</td><td className="px-4 py-3 font-semibold">{won(originalContractAmount)}</td><td className="px-4 py-3 font-semibold text-emerald-700">{won(paid)}</td><td className="px-4 py-3 font-semibold text-red-600">{won(outstanding)}</td><td className="px-4 py-3">{c.lenderCount}개</td><td className="max-w-[260px] truncate px-4 py-3" title={c.memo}>{c.memo||"-"}</td><td className="px-4 py-3">{view==="risk"?<div className="flex justify-end gap-2"><Button variant="danger" onClick={e=>{e.stopPropagation();promote(c)}}>사고자 등록</Button><Button variant="secondary" onClick={e=>{e.stopPropagation();release(c)}}>해지</Button></div>:<div className="flex justify-end"><Button variant="secondary" onClick={e=>{e.stopPropagation();releaseAccident(c)}}>사고자 해제</Button></div>}</td></tr>{expanded&&<tr className={view==="risk"?"border-t border-amber-100 bg-white":"border-t border-red-100 bg-white"}><td colSpan={11} className="px-5 py-5"><div className={`rounded-2xl border p-5 ${view==="risk"?"border-amber-100 bg-amber-50/30":"border-red-100 bg-red-50/30"}`}><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div><div className="font-bold text-slate-900">{c.name} 고객정보</div><div className="mt-1 text-xs text-slate-500">계약 원금과 실제 납부내역을 기준으로 표시합니다.</div></div><div className="flex items-center gap-2"><Badge tone={view==="risk"?"amber":"red"}>{view==="risk"?"사고 위험자":"사고자"}</Badge><Badge tone={status.tone}>{status.label}</Badge></div></div><div className="mb-4 grid gap-3 sm:grid-cols-3"><div className="rounded-xl border border-slate-200 bg-white px-4 py-4"><div className="text-[11px] font-semibold text-slate-400">총 계약금액</div><div className="mt-1 text-lg font-bold text-slate-900">{won(originalContractAmount)}</div></div><div className="rounded-xl border border-emerald-200 bg-emerald-50/50 px-4 py-4"><div className="text-[11px] font-semibold text-emerald-600">실납부액</div><div className="mt-1 text-lg font-bold text-emerald-700">{won(paid)}</div></div><div className="rounded-xl border border-red-200 bg-red-50/60 px-4 py-4"><div className="text-[11px] font-semibold text-red-500">미수금</div><div className="mt-1 text-lg font-bold text-red-600">{won(outstanding)}</div></div></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["등록일",c.createdAt||"-"],["연락처",c.phone||"-"],["주소",c.address||"-"],["생년월일/주민번호",c.birthNumber||"-"],["영업 담당자",c.manager||"-"],["조율 담당자",c.coordinationManager||"-"],["계약일",c.contractDate||"-"],["계약금액",won(originalContractAmount)],["실납부액",won(paid)],["미수금",won(outstanding)],["선납금",won(c.prepaidAmount)],["세후 월급여",c.monthlyNetSalary?won(c.monthlyNetSalary):"-"],["급여일",c.salaryDay?`매월 ${c.salaryDay}일`:"-"],["분납기간",`${c.installmentMonths||0}개월`],["업체당 단가",won(c.lenderUnitPrice)],["업체 수",`${c.lenderCount||0}개`]].map(([label,value])=><div key={label} className="rounded-xl border border-slate-200 bg-white px-4 py-3"><div className="text-[11px] font-semibold text-slate-400">{label}</div><div className="mt-1 break-words text-sm font-semibold text-slate-800">{value}</div></div>)}</div><div className="mt-3 rounded-xl border border-slate-200 bg-white px-4 py-3"><div className="text-[11px] font-semibold text-slate-400">메모</div><div className="mt-1 whitespace-pre-wrap text-sm leading-6 text-slate-700">{c.memo||"-"}</div></div>{view==="risk"?<div className="mt-4 flex justify-end gap-2"><Button variant="secondary" onClick={()=>release(c)}>해지</Button><Button variant="danger" onClick={()=>promote(c)}>사고자 등록</Button></div>:<div className="mt-4 flex justify-end"><Button variant="secondary" onClick={()=>releaseAccident(c)}>사고자 해제</Button></div>}</div></td></tr>}</Fragment>})}{rows.length===0&&<tr><td colSpan={11} className="px-4 py-12 text-center text-sm text-slate-400">{view==="risk"?"사고 위험자로 등록된 고객이 없습니다.":"사고자로 등록된 고객이 없습니다."}</td></tr>}</tbody></table></div><Pagination page={page} total={rows.length} onChange={p=>{setPage(p);setExpandedId(null)}} pageSize={10}/></Card>
 </>
}

function RepaymentEdit({repayment,onClose}:{repayment:Repayment;onClose:()=>void}){
 const store=useAdminStore();const customer=store.customers.find(row=>row.id===repayment.customerId);
 return customer?<RepaymentScheduleModal open customer={customer} initialScheduleId={repayment.id} onClose={onClose}/>:null;
}

type SettlementDraft=Omit<Settlement,"id">;
const emptySettlement=():SettlementDraft=>({paidDate:today(),clientName:"",amount:0,paymentMethod:"계좌이체",memo:""});
function Lenders(){const s=useAdminStore();const [page,setPage]=useState(1);const [q,setQ]=useState("");const [open,setOpen]=useState(false);const [editing,setEditing]=useState<Lender|null>(null);const [form,setForm]=useState(emptyLender());const [del,setDel]=useState<Lender|null>(null);const [customerPickerOpen,setCustomerPickerOpen]=useState(false);const [customerQ,setCustomerQ]=useState("");const rows=useMemo(()=>s.lenders.filter(l=>`${l.name} ${l.contacts.map(c=>c.value).join(" ")} ${l.account} ${l.customerIds.map(id=>{const c=s.customers.find(x=>x.id===id);return `${c?.name||""} ${c?.phone||""}`}).join(" ")}`.toLowerCase().includes(q.toLowerCase())).sort(newestFirst),[s.lenders,s.customers,q]);const customerRows=useMemo(()=>s.customers.filter(c=>!form.customerIds.includes(c.id)&&`${c.name} ${c.phone}`.toLowerCase().includes(customerQ.toLowerCase())).sort(newestFirst),[s.customers,form.customerIds,customerQ]);function beginAdd(){setEditing(null);setForm(emptyLender());setCustomerQ("");setOpen(true)}function beginEdit(l:Lender){setEditing(l);setForm({...l,contacts:l.contacts.map(c=>({...c})),customerIds:[...l.customerIds]});setCustomerQ("");setOpen(true)}function save(){const clean={...form,contacts:form.contacts.map(c=>({...c,value:c.value||""}))};if(editing)s.updateLender(editing.id,clean);else s.addLender(clean);setOpen(false)}function addCustomer(id:string){if(!form.customerIds.includes(id))setForm({...form,customerIds:[...form.customerIds,id]})}return <><PageHeader title="사채업체 관리" description="업체 연락정보와 해당 업체를 이용한 의뢰인을 함께 관리합니다." action={<Button onClick={beginAdd}><Plus size={15}/>업체 등록</Button>}/><div className="mb-4 grid gap-3 sm:grid-cols-[220px_1fr]"><Card className="flex items-center justify-between px-4 py-3"><div><div className="text-xs font-semibold text-slate-500">총 등록 사채업체</div><div className="mt-1 text-2xl font-bold text-slate-900">{s.lenders.length.toLocaleString()}<span className="ml-1 text-sm font-semibold text-slate-500">개</span></div></div></Card><Card className="p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1)}} placeholder="업체명, 연락정보 또는 이용 의뢰인 검색"/></Card></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[850px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["등록일","업체명","이용 의뢰인","연락수단","연락정보","계좌번호","특이사항",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(l=><tr key={l.id} className="border-t border-slate-100"><td className="px-4 py-3">{l.createdAt}</td><td className="px-4 py-3 font-semibold">{l.name}</td><td className="px-4 py-3">{l.customerIds.map(id=>s.customers.find(c=>c.id===id)?.name).filter(Boolean).join(", ")||"-"}</td><td className="px-4 py-3">{l.contacts.map(c=>c.type).join(", ")}</td><td className="px-4 py-3">{l.contacts.map(c=>c.value).join(" / ")||"-"}</td><td className="px-4 py-3">{l.account||"-"}</td><td className="px-4 py-3">{l.memo||"-"}</td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="secondary" onClick={()=>beginEdit(l)}>수정</Button><Button variant="danger" onClick={()=>setDel(l)}>삭제</Button></div></td></tr>)}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card><Modal open={open} title={editing?"사채업체 수정":"사채업체 등록"} onClose={()=>setOpen(false)}><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Label text="등록일"><input type="date" className={field} value={form.createdAt} onChange={e=>setForm({...form,createdAt:e.target.value})}/></Label><Label text="업체명"><input className={field} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Label></div><div><div className="mb-2 flex items-center justify-between"><b className="text-sm">연락수단 / 계정</b><Button variant="secondary" onClick={()=>setForm({...form,contacts:[...form.contacts,{id:`LC-${Date.now()}-${form.contacts.length}`,type:"번호",value:""}]})}><Plus size={14}/>추가</Button></div><div className="space-y-2">{form.contacts.map(c=><div key={c.id} className="grid grid-cols-1 gap-2 sm:grid-cols-[130px_1fr_auto]"><select className={field} value={c.type} onChange={e=>setForm({...form,contacts:form.contacts.map(x=>x.id===c.id?{...x,type:e.target.value as ContactType}:x)})}>{contactTypes.map(x=><option key={x}>{x}</option>)}</select><input className={field} value={c.value} onChange={e=>setForm({...form,contacts:form.contacts.map(x=>x.id===c.id?{...x,value:e.target.value}:x)})} placeholder="번호 또는 SNS 아이디"/><Button variant="danger" onClick={()=>{if(form.contacts.length>1)setForm({...form,contacts:form.contacts.filter(x=>x.id!==c.id)})}}>삭제</Button></div>)}</div></div><div><div className="mb-1.5 flex items-center justify-between"><div className="text-sm font-semibold">이용 의뢰인</div><Button variant="secondary" onClick={()=>{setCustomerQ("");setCustomerPickerOpen(true)}}><UserRoundSearch size={15}/>의뢰인 검색</Button></div><div className="flex flex-wrap gap-2 rounded-xl border border-slate-200 bg-slate-50 p-3">{form.customerIds.map(id=>{const c=s.customers.find(x=>x.id===id);return c?<span key={id} className="inline-flex items-center gap-1 rounded-full bg-blue-50 px-2.5 py-1 text-xs font-semibold text-blue-700">{c.name} · {c.phone}<button type="button" className="ml-1 text-blue-400 hover:text-red-600" onClick={()=>setForm({...form,customerIds:form.customerIds.filter(x=>x!==id)})}>×</button></span>:null})}{form.customerIds.length===0&&<span className="text-xs text-slate-400">등록된 이용 의뢰인이 없습니다.</span>}</div></div><Label text="계좌번호"><input className={field} value={form.account} onChange={e=>setForm({...form,account:e.target.value})} placeholder="은행 / 계좌번호 / 예금주"/></Label><Label text="특이사항"><textarea className={textarea} value={form.memo} onChange={e=>setForm({...form,memo:e.target.value})}/></Label><div className="flex justify-end gap-2"><Button variant="secondary" onClick={()=>setOpen(false)}>취소</Button><Button onClick={save}>저장</Button></div></div></Modal><Modal open={customerPickerOpen} title="이용 의뢰인 검색" onClose={()=>setCustomerPickerOpen(false)}><div className="space-y-3"><SearchBox value={customerQ} onChange={setCustomerQ} onReset={()=>setCustomerQ("")} placeholder="고객명 또는 전화번호 검색"/><div className="max-h-[420px] overflow-auto rounded-xl border border-slate-200"><table className="admin-responsive-table w-full text-sm"><thead className="sticky top-0 bg-slate-50 text-left text-xs text-slate-500"><tr><th className="px-4 py-3">고객명</th><th className="px-4 py-3">연락처</th><th className="px-4 py-3">영업</th><th className="px-4 py-3"></th></tr></thead><tbody>{customerRows.map(c=><tr key={c.id} className="border-t border-slate-100"><td className="px-4 py-3 font-semibold">{c.name}</td><td className="px-4 py-3">{c.phone}</td><td className="px-4 py-3">{c.manager}</td><td className="px-4 py-3 text-right"><Button onClick={()=>addCustomer(c.id)}>추가</Button></td></tr>)}{customerRows.length===0&&<tr><td colSpan={4} className="px-4 py-10 text-center text-slate-400">추가할 의뢰인이 없습니다.</td></tr>}</tbody></table></div><div className="flex justify-end"><Button variant="secondary" onClick={()=>setCustomerPickerOpen(false)}>완료</Button></div></div></Modal><ConfirmDelete open={!!del} name={del?.name||"업체"} label="사채업체 정보" onClose={()=>setDel(null)} onConfirm={()=>{if(del)s.deleteLender(del.id)}}/></>}
function Board(){const s=useAdminStore();const [page,setPage]=useState(1);const [q,setQ]=useState("");const [open,setOpen]=useState(false);const [view,setView]=useState<string|null>(null);const [editing,setEditing]=useState<string|null>(null);const [del,setDel]=useState<string|null>(null);const empty=()=>({title:"",body:"",writer:"홍성원",date:today(),isNotice:false,noticeOrder:1,attachments:[] as Attachment[]});const [form,setForm]=useState(empty());const rows=useMemo(()=>s.posts.filter(p=>`${p.title} ${p.body} ${p.writer}`.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>a.isNotice!==b.isNotice?(a.isNotice?-1:1):a.isNotice?(a.noticeOrder-b.noticeOrder||newestFirst(a,b)):newestFirst(a,b)),[s.posts,q]);const viewing=s.posts.find(p=>p.id===view);function add(){setEditing(null);setForm(empty());setOpen(true)}function edit(p:BoardPost){setEditing(p.id);setForm({title:p.title,body:p.body,writer:p.writer,date:p.date,isNotice:p.isNotice,noticeOrder:p.noticeOrder,attachments:[...p.attachments]});setOpen(true)}async function files(fs:FileList|null){if(!fs)return;const next=[...form.attachments];for(const file of Array.from(fs)){const id=`F-${Date.now()}-${Math.random()}`;const storagePath=await saveFile(id,file);next.push({id,name:file.name,size:file.size,type:file.type,storagePath})}setForm({...form,attachments:next})}async function save(){editing?s.updatePost(editing,form):s.addPost(form);setOpen(false)}async function download(a:Attachment){const blob=await getFile(a.storagePath);if(!blob)return alert("첨부파일을 불러오지 못했습니다.");const url=URL.createObjectURL(blob);const x=document.createElement("a");x.href=url;x.download=a.name;x.click();URL.revokeObjectURL(url)}return <><PageHeader title="내부 게시판" description="공지 고정, 순서 설정, 본문 및 파일 첨부를 지원합니다." action={<Button onClick={add}><Plus size={15}/>글 생성</Button>}/><Card className="mb-4 p-3"><SearchBox value={q} onChange={v=>{setQ(v);setPage(1)}} onReset={()=>{setQ("");setPage(1)}} placeholder="제목, 본문 또는 작성자 검색"/></Card><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="admin-responsive-table w-full min-w-[850px] text-sm"><thead className="bg-slate-50 text-left text-xs text-slate-500"><tr>{["구분","제목","작성자","등록일","첨부",""].map(h=><th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody>{pageRows(rows,page).map(p=><tr key={p.id} className="border-t border-slate-100"><td className="px-4 py-3">{p.isNotice?<Badge tone="blue">공지 {p.noticeOrder}</Badge>:"일반"}</td><td className="px-4 py-3"><button className="font-semibold hover:text-blue-700" onClick={()=>setView(p.id)}>{p.title}</button></td><td className="px-4 py-3">{p.writer}</td><td className="px-4 py-3">{p.date}</td><td className="px-4 py-3">{p.attachments.length?`${p.attachments.length}개`:"-"}</td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="secondary" onClick={()=>edit(p)}>수정</Button><Button variant="danger" onClick={()=>setDel(p.id)}>삭제</Button></div></td></tr>)}</tbody></table></div><Pagination page={page} total={rows.length} onChange={setPage}/></Card><Modal open={open} title={editing?"게시글 수정":"게시글 생성"} onClose={()=>setOpen(false)}><div className="space-y-4"><Label text="제목"><input className={field} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Label><Label text="본문"><textarea className={`${textarea} min-h-48`} value={form.body} onChange={e=>setForm({...form,body:e.target.value})}/></Label><div className="grid gap-3 sm:grid-cols-2"><Label text="작성자"><input className={field} value={form.writer} onChange={e=>setForm({...form,writer:e.target.value})}/></Label><Label text="등록일"><input type="date" className={field} value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></Label></div><div className="flex items-center gap-3"><label className="flex items-center gap-2 text-sm font-semibold"><input type="checkbox" checked={form.isNotice} onChange={e=>setForm({...form,isNotice:e.target.checked})}/>공지사항</label>{form.isNotice&&<NumberInput min={1} className="w-28" value={form.noticeOrder} onChange={v=>setForm({...form,noticeOrder:v})}/>}</div><div><label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold hover:bg-slate-50"><Paperclip size={15}/>파일 첨부<input type="file" multiple className="hidden" onChange={e=>files(e.target.files)}/></label><div className="mt-2 space-y-1">{form.attachments.map(a=><div key={a.id} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-xs"><span>{a.name} · {(a.size/1024/1024).toFixed(2)}MB</span><button className="text-red-600" onClick={async()=>{await deleteFile(a.storagePath);setForm({...form,attachments:form.attachments.filter(x=>x.id!==a.id)})}}>삭제</button></div>)}</div></div><div className="flex justify-end gap-2"><Button variant="secondary" onClick={()=>setOpen(false)}>취소</Button><Button onClick={save}>저장</Button></div></div></Modal><Modal open={!!viewing} title={viewing?.title||"게시글"} onClose={()=>setView(null)}>{viewing&&<div><div className="mb-4 flex gap-3 text-xs text-slate-400"><span>{viewing.writer}</span><span>{viewing.date}</span>{viewing.isNotice&&<Badge tone="blue">공지</Badge>}</div><div className="whitespace-pre-wrap text-sm leading-7">{viewing.body}</div>{viewing.attachments.length>0&&<div className="mt-5 border-t border-slate-100 pt-4"><b className="text-sm">첨부파일</b><div className="mt-2 space-y-2">{viewing.attachments.map(a=><button key={a.id} onClick={()=>download(a)} className="flex w-full items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-sm hover:bg-blue-50"><span>{a.name}</span><Download size={15}/></button>)}</div></div>}</div>}</Modal><ConfirmDelete open={!!del} name={s.posts.find(p=>p.id===del)?.title||"게시글"} label="게시글" onClose={()=>setDel(null)} onConfirm={()=>{if(del)s.deletePost(del)}}/></>}
